package com.bjjj.todo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class WidgetTests extends Instrumentation {
 View findComplete(View v){if(v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith("完成 组件测试"))return v;if(v instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){View found=findComplete(group.getChildAt(i));if(found!=null)return found;}return null;}
 View findCard(View v,String title){if(v.getContentDescription()!=null&&v.getContentDescription().toString().equals("完成 "+title))return (View)v.getParent();if(v instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=findCard(group.getChildAt(n),title);if(found!=null)return found;}return null;}
 String js(MainActivity activity,String expression)throws Exception{String[] result={null};java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);runOnMainSync(()->activity.web.evaluateJavascript(expression,value->{result[0]=value;done.countDown();}));check(done.await(10,java.util.concurrent.TimeUnit.SECONDS),"WebView callback completed");return result[0];}
 void capture(Context c,String name)throws Exception{waitForIdleSync();Thread.sleep(400);try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle status=new Bundle();status.putString("id","InstrumentationTestRunner");status.putInt("numtests",1);status.putInt("current",1);status.putString("class",getClass().getName());status.putString("test","persistenceAndNativeWidget");sendStatus(1,status);AppWidgetHost[] host={null};try{Context c=getTargetContext();c.deleteFile("tasks.json");JSONObject draft=new JSONObject().put("title","组件测试：论文图表核对").put("priority","high").put("category","research").put("due",java.time.Instant.now().plusSeconds(7200).toString()).put("offsets",new JSONArray());JSONObject task=Store.save(c,draft);check(Store.open(Store.read(c)).size()==1,"Task persisted");try{Store.save(c,new JSONObject().put("title"," "));throw new AssertionError("Empty title accepted");}catch(IllegalArgumentException ignored){}catch(Exception expected){}Store.done(c,task.getString("id"),true);Store.done(c,task.getString("id"),true);check(Store.open(Store.read(c)).isEmpty(),"Completion must be idempotent");Store.done(c,task.getString("id"),false);check(Reminder.offsetMillis(1d/60)==1000,"One second conversion");check(Reminder.offsetMillis(7d/60)==7000,"Seconds are rounded without truncation");check(Reminder.offsetMillis(30)==1800000,"Legacy minute conversion");for(String level:new String[]{"normal","low"})Store.save(c,new JSONObject().put("title","组件测试："+level).put("priority",level));
  JSONObject model=new JSONObject(Store.read(c).toString());JSONObject cloud=new JSONObject().put("owner","test-owner").put("base",new JSONObject());model.put("cloud",cloud);JSONObject sent=SyncProtocol.snapshot(model),remote=new JSONObject().put("id",task.getString("id")).put("revision",1).put("deleted",false).put("data",SyncProtocol.payload(model.getJSONArray("tasks").getJSONObject(0)));JSONArray rows=new JSONArray();for(int n=0;n<model.getJSONArray("tasks").length();n++){JSONObject item=model.getJSONArray("tasks").getJSONObject(n);rows.put(new JSONObject().put("id",item.getString("id")).put("revision",1).put("deleted",false).put("data",SyncProtocol.payload(item)));}SyncProtocol.apply(model,sent,new JSONObject().put("rows",rows).put("results",new JSONArray()));check(SyncProtocol.snapshot(model).getJSONArray("changes").length()==0,"Synced state must not upload again");model.getJSONArray("tasks").getJSONObject(0).put("title","离线修改");sent=SyncProtocol.snapshot(model);remote.getJSONObject("data").put("title","其他设备修改");remote.put("revision",2);SyncProtocol.apply(model,sent,new JSONObject().put("rows",new JSONArray().put(remote)).put("results",new JSONArray().put(new JSONObject().put("id",task.getString("id")).put("ok",false))));check(model.getJSONArray("tasks").length()==4,"Conflict must preserve both versions");CloudSync.save(c,new JSONObject().put("refresh_token","test-secret").put("expires_in",3600));check(CloudSync.load(c).getString("refresh_token").equals("test-secret"),"Keystore session roundtrip");check(!new String(CloudSync.sessionFile(c).readFully(),java.nio.charset.StandardCharsets.ISO_8859_1).contains("test-secret"),"Session must not be stored as plaintext");check(c.checkSelfPermission(android.Manifest.permission.ACCESS_NETWORK_STATE)==android.content.pm.PackageManager.PERMISSION_GRANTED,"Network state permission installed");android.app.job.JobScheduler scheduler=c.getSystemService(android.app.job.JobScheduler.class);try{CloudSync.scheduleJobs(c);check(scheduler.getPendingJob(91)!=null&&scheduler.getPendingJob(92)!=null,"Authenticated background jobs scheduled");check(scheduler.getPendingJob(91).isPeriodic(),"Periodic sync retained");}finally{scheduler.cancel(91);scheduler.cancel(92);}
  JSONObject large=new JSONObject().put("tasks",new JSONArray()).put("cloud",new JSONObject().put("base",new JSONObject()));JSONArray oldRows=new JSONArray();for(int n=0;n<105;n++){String id=String.format(java.util.Locale.ROOT,"item%03d",n);JSONObject item=new JSONObject().put("id",id).put("title","本机修改");large.getJSONArray("tasks").put(item);JSONObject oldData=SyncProtocol.payload(item);oldData.put("title","原内容");JSONObject r=new JSONObject().put("id",id).put("revision",1).put("deleted",false).put("data",oldData);large.getJSONObject("cloud").getJSONObject("base").put(id,r);oldRows.put(r);}JSONObject largeSent=SyncProtocol.snapshot(large);check(largeSent.getJSONArray("changes").length()==100&&largeSent.getJSONArray("dirty").length()==105,"Bounded batch tracks all dirty items");SyncProtocol.apply(large,largeSent,new JSONObject().put("rows",oldRows).put("results",new JSONArray()));check(large.getJSONArray("tasks").getJSONObject(104).getString("title").equals("本机修改"),"Unsent local changes must survive pull");
  MainActivity activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(!activity.isFinishing(),"App resumes with encrypted login session");scheduler.cancel(91);scheduler.cancel(92);CloudSync.sessionFile(c).delete();
  boolean calendarReady=false;for(int attempt=0;attempt<80;attempt++){if("true".equals(js(activity,"typeof window.renderMobileCalendar==='function' && document.querySelectorAll('#mobile-week .calendar-date').length===7"))){calendarReady=true;break;}Thread.sleep(100);}check(calendarReady,"Native WebView loads shared calendar");check("true".equals(js(activity,"getComputedStyle(document.getElementById('mobile-week')).display==='grid'")),"Native calendar stylesheet applied");
  check("true".equals(js(activity,"document.getElementById('mobile-month-tab').click();document.querySelectorAll('#mobile-month-days .calendar-date').length>=35")),"Month overview works in native WebView");
  check("true".equals(js(activity,"document.getElementById('mobile-day-add').click();document.getElementById('due').value===window.mobileCalendarSelected()+'T17:00'")),"Selected date prefilled in editor");js(activity,"document.getElementById('cancel').click()");capture(c,"app-calendar-test.png");
  CloudSync.error="";check("true".equals(js(activity,"document.getElementById('prefs').click();!!document.getElementById('cloud-form') && document.getElementById('settings').open")),"Native login card loads");check("true".equals(js(activity,"getComputedStyle(document.getElementById('cloud-panel')).borderRadius==='18px'")),"Native shared account stylesheet applied");
  check("true".equals(js(activity,"document.getElementById('cloud-tab-signup').click();!document.getElementById('cloud-signup').hidden")),"Native registration tab works");js(activity,"document.getElementById('cloud-tab-login').click()");capture(c,"app-login-test.png");js(activity,"document.getElementById('close-settings').click()");
  int[] widgetId={0};AppWidgetHostView[] view={null};runOnMainSync(()->{host[0]=new AppWidgetHost(activity,201);widgetId[0]=host[0].allocateAppWidgetId();AppWidgetManager m=AppWidgetManager.getInstance(activity);Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,350);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,600);check(m.bindAppWidgetIdIfAllowed(widgetId[0],new ComponentName(activity,TodoWidget.class),options),"Widget binding permission");view[0]=host[0].createView(activity,widgetId[0],m.getAppWidgetInfo(widgetId[0]));activity.setContentView(view[0]);host[0].startListening();TodoWidget.updateAll(activity);});
  View[] checkbox={null};for(int attempt=0;attempt<80&&checkbox[0]==null;attempt++){Thread.sleep(250);runOnMainSync(()->checkbox[0]=findComplete(view[0]));}waitForIdleSync();Thread.sleep(1200);try(java.io.FileOutputStream output=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),"widget-test.png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,output);}check(checkbox[0]!=null,"Native scrolling collection rendered");runOnMainSync(()->{String[] names={"组件测试：论文图表核对","组件测试：normal","组件测试：low"};int[] colors={0xfff1d1d5,0xfff2e4bc,0xffcfdfef};for(int n=0;n<names.length;n++){View card=findCard(view[0],names[n]);check(card!=null,"Priority row is visible");check(((android.graphics.drawable.GradientDrawable)card.getBackground()).getColor().getDefaultColor()==colors[n],"Priority card background");}});runOnMainSync(()->checkbox[0].performClick());for(int i=0;i<40&&Store.open(Store.read(c)).size()!=2;i++)Thread.sleep(150);check(Store.open(Store.read(c)).size()==2,"Widget checkbox persisted completion");runOnMainSync(()->{host[0].deleteAppWidgetId(widgetId[0]);host[0].stopListening();activity.finish();});status.putString("stream","\nPassed persistence, validation, idempotent completion and native AppWidget list click.\n");sendStatus(0,status);Bundle result=new Bundle();result.putString("stream","\nOK (1 test)\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){status.putString("stack",android.util.Log.getStackTraceString(e));sendStatus(-2,status);Bundle result=new Bundle();result.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
